    "explanation": "Büyüme ve hızlı doku yapımı dönemindeki bebek ve küçük çocuklarda vücut sentez kapasitesi yetersiz kaldığı için **histidin** (ve arginin) esansiyel kabul edilir; diyette mutlaka yer almalıdır. Erişkinde ise endojen sentez pozitif azot dengesini sürdürmeye genellikle yeterlidir.",
