    "explanation": "Ksenobiyotik biyotransformasyonunda **Faz II reaksiyonları konjugasyon** reaksiyonlarıdır; glukuronik asit, sülfat, glutatyon veya **glisin** gibi endojen hidrofilik grupların bağlanmasıyla toksik bileşiklerin polaritesi ve suda çözünürlüğü artırılarak idrar veya safrayla atılımı sağlanır.",
    "note": "",
