    "explanation": "Organofosfat ve karbamat grubu insektisitler asetilkolinesteraz enzimini inhibe ederek toksisite oluştururlar; bu zehirlenmelerin tanısında ve klinik takibinde serumda **kolinesteraz** (psödokolinesteraz) ve eritrosit asetilkolinesteraz aktivitesi ölçülür.",
