    "open_answer": "",
    "explanation": "Fenilketonüride biriken fenilalanin transaminasyon ve dekarboksilasyon yollarıyla fenilpirüvat, fenillaktat, fenilasetat ve **fenilasetilglutamin**'e dönüşerek idrarla atılır. **Orotik asit** ise pirimidin biyosentezi veya üre döngüsü enzim defektlerinde görülür.",
