    "professor": "Belirtilmemiş",
    "question": "İlacın metabolize edildikten sonra safrayla barsağa atılmasının ardından barsak bakterilerinin ilacı yeniden aktif hale çevirmeleri sonucu ilacın yeniden emilmesi durumu neyi ifade eder?",
