    "explanation": "İki ilacın birlikte kullanıldığında oluşturdukları toplam biyolojik yanıtın, her birinin tek başına oluşturdukları etkilerin aritmetik toplamından belirgin biçimde daha büyük olması durumuna **supra-aditif etki (potansiyalizasyon)** adı verilir.",
