    "explanation": "Erkeklerde tek bir X kromozomu (XY) bulunduğu için erkekler mutant X'i aldıklarında doğrudan hasta olurlar; erkeklerin 'taşıyıcı' olması söz konusu olamaz. Taşıyıcı bir kadının erkek çocukları %50 hasta, **%50 sağlıklı** olacaktır. Bu yüzden D yanlıştır.",
