    "question": "\"......................................\"; küçük bir mandibula ve U-şeklinde yarık damak vardır.Primer anomali mikrognatidir, dil yukarı doğru itilir, damağı oluşturan yapılar orta hatta birleşemezve bu nedenle U- şeklinde yarık damak oluşur.Yukarıdaki cümlede yer alan boşluğu uygun kelime/kelimeler ile doldurunuz.",
