    "open_answer": "",
    "explanation": "Tümör baskılayıcı gen olan **TP53**'ün germ-line (kalıtsal) inaktive edici mutasyonları, genç yaşta osteosarkom, yumuşak doku sarkomu, meme kanseri ve adrenal korteks karsinomu ile karakterize **Li-Fraumeni sendromuna** neden olur.",
    "note": "",
    "q_type": "mcq",
    "incomplete": false,
