    "explanation": "DNA çift zincir kırıklarının homolog rekombinasyonla hatasız onarımında görev alan **BRCA1 ve BRCA2** tümör baskılayıcı genlerindeki germline mutasyonlar, kalıtsal meme ve over kanseri sendromuna yol açar.",
