    "year": "2020-2021",
    "q_num": 24,
    "subject": "Tıbbi Genetik",
    "professor": "Belirtilmemiş",
    "question": "Gen tedavisi uygulamaları için kullanılan vektörler hakkında aşağıda sıralanan bilgilerden hangisi hatalıdır?",
    "options": [
      {
        "letter": "A",
        "text": "Retrovirüs bölünmeyen hücreleri enfekte edebilir."
      },
      {
        "letter": "B",
        "text": "Adenovirüs olumsuz immünolojik yanıt gösterir."
      },
      {
        "letter": "C",
        "text": "Herpesvirüsün sitotoksik etkisi vardır."
      },
      {
        "letter": "D",
        "text": "Adeno-assosiye virüs kısıtlı yabancı sahiptir."
      },
      {
        "letter": "E",
        "text": "Tüm virüslerin ortak dezavantajı genin yanlış bir yere yerleşme tehlikesidir. moleküler tanı yöntemleri aşağıdakilerden"
      }
    ],
    "answer": "A",
    "open_answer": "",
    "explanation": "Klasik **retrovirüs vektörleri** nükleer porlardan aktif taşınamadığından konak genomuna entegre olabilmek için mitoz sırasında çekirdek zarının yıkılmasına ihtiyaç duyar ve bu nedenle **bölünmeyen (postmitotik) hücreleri enfekte edemez** (A yanlış). Adenovirüs vektörleri konakta viral proteinlere karşı güçlü humoral ve hücresel immünolojik yanıt uyandırarak enflamasyona yol açma dezavantajına sahiptir (B doğru). Herpes simpleks virüs (HSV) vektörleri konak hücre üzerinde doğrudan sitotoksik etki gösterebilir (C doğru). Adeno-assosiye virüs (AAV) küçük kapsidi nedeniyle sınırlı yabancı gen taşıma kapasitesine (yaklaşık 4.5-5 kb) sahiptir (D doğru). Viral vektörlerin konak genomuna entegre olurken yanlış bir lokusa yerleşmesi sonucu insersiyonel mutagenez veya onkogen aktivasyonu yapma tehlikesi temel ortak güvenlik riskidir (şık sonunda OCR ile başka soru kökünün parçası yapışmıştır) (E doğru).",
    "note": "Cevap anahtarı tıbbi literatüre göre tamamlanmıştır.",
