    "explanation": "Doku kesitlerinde patolojik distrofik ve metastatik kalsiyum birikimlerini histokimyasal olarak gümüşleme reaksiyonuyla siyah renkte gösteren özel boya **von Kossa boyasıdır**; Prusya mavisi ise hemosiderin demirini gösterir.",
