    "professor": "Belirtilmemiş",
    "question": "Nonspesifik akut inflamasyonda rol oynayan temel hücre hangisidir?",
    "options": [
      {
        "letter": "A",
        "text": "T lenfosit"
      },
      {
        "letter": "B",
        "text": "B lenfosit"
      },
      {
        "letter": "C",
        "text": "Plazma hücresi"
      },
      {
        "letter": "D",
        "text": "Nötrofil"
      },
      {
        "letter": "E",
        "text": "Mast hücresi"
      }
    ],
    "answer": "D",
    "open_answer": "",
    "explanation": "Nonspesifik akut inflamatuar yanıtta postkapiller venüllerden hasarlı dokuya ilk 6-24 saatte hızla göç eden ve mikroorganizmaları fagositozla ortadan kaldıran primer lökosit tipi **nötrofillerdir**.",
    "note": "Cevap anahtarı tıbbi literatüre göre tamamlanmıştır.",
