    "explanation": "Çekum tabanından köken alan appendix vermiformis en sık yaklaşık %65 sıklıkla çekumun arkasında yani **retrosekal (retrocaecal)** pozisyonda yerleşir; pelvik yerleşim ise ikinci sıklıkta görülür.",
