    "professor": "Belirtilmemiş",
    "question": "Midenin fundus bölümünü besleyen arteria gastrica brevis 'ler hangi arterin dalıdır?",
    "options": [
      {
        "letter": "A",
        "text": "arteria splenica"
      },
      {
        "letter": "B",
        "text": "arteria gastrica dextra"
      },
      {
        "letter": "C",
        "text": "arteria hepatica communis"
      },
      {
        "letter": "D",
        "text": "arteria hepatica propria"
      },
      {
        "letter": "E",
        "text": "arteria gastroomentalis dextra"
      }
    ],
    "answer": "A",
    "open_answer": "",
    "explanation": "Midenin fundusunu besleyen 4-5 adet kısa arter olan **aa. gastricae breves**, lig. gastrosplenicum içinde seyreder ve **arteria splenica (lienalis)**'nın terminal dallarından çıkar.",
    "note": "",
