    "question": "Aşağıdaki boşlukları uygun transport sistemi ile doldurunuz.İnce bağırsak lümeni içindeki glukoz ve galaktoz ........................................, fruktoz ve diğer monosakkaritler ise ................................. ince bağırsak epitel hücresi içine alınırlar ve oradan kana geçerler.",
