    "open_answer": "",
    "explanation": "Karaciğer hepatositlerinin düz endoplazmik retikulumunda (mikrozomlarda) yer alan ve ksenobiyotiklerin Faz I oksidasyon, hidroksilasyon reaksiyonlarını katalizleyen miks fonksiyonlu monooksijenaz enzim ailesine **Sitokrom P450 (CYP450)** denir.",
