    "explanation": "Karaciğer glikojen, lipidler, demir, bakır ile yağda eriyen vitaminler (A, D, K) ve B₁₂ vitaminini depolar. Suda eriyen vitaminlerden olan **B₆ vitamini (piridoksin)** ise karaciğerde uzun süreli büyük depolar oluşturmaz ve vücuttan hızla metabolize olup atılır.",
