    "explanation": "İyonize edici radyasyon ve ışınlar DNA çift zincir kırıkları ve nokta mutasyonları oluşturarak onkogen aktivasyonuna ve tümör baskılayıcı gen inaktivasyonuna neden olur; bu durum hücresel düzeyde kontrolsüz proliferasyona ve **neoplaziye** yol açar.",
    "note": "",
