    "open_answer": "",
    "explanation": "İnsülin anabolik bir hormondur; glikoliz, glikojenez ve lipojenezi uyarır. **Ketojenez** ise açlık ve insülin yetersizliğinde yağ asidi beta-oksidasyonunun artmasıyla aktive olan bir katabolik süreçtir; insülin ketojenezi güçlü bir şekilde inhibe eder.",
