    "open_answer": "",
    "explanation": "Sorbitol, asesülfam K, siklamat ve sakkarin tatlandırıcı maddelerdir. **Sülfitler** ise gıda sanayisinde antimikrobiyal koruyucu ve antioksidan (renk kararmasını önleyici katkı maddesi) olarak kullanılır; tatlandırıcı amaçla kullanılmaz.",
    "note": "",
    "q_type": "mcq",
