    "subject": "Biyokimya",
    "professor": "Ayşe Özdemir",
    "question": "4-6 aylar arasında görünür hale gelen, büyüme gecikmesi, zeka geriliği, duyma hassasiyeti, bunama, körlük, retinada kiraz kırmızısı noktalar, kas halsizliği ile giden Gangliozid lipidozisi (Tay-Sachs hastalığı) hastalığında hangisi görülür?",
