    "answer": "E",
    "open_answer": "",
    "explanation": "Otozomal resesif geçişli bir lizozomal depo hastalığı olan GM2 gangliozidozunda (**Tay-Sachs hastalığı**), lizozomal **hekzoaminidaz A** enzim aktivitesi eksiktir; nöronlarda GM2 gangliozidi birikerek körlük ve retinada kiraz kırmızısı lekeye yol açar.",
