    "open_answer": "",
    "explanation": "Apoptozisin **intrensek (mitokondriyal) yolağı**; hücre içi stres, DNA hasarı ve büyüme faktörü yoksunluğunda Bcl-2 ailesi proteinleri kontrolünde mitokondriden sitokrom c salınımıyla aktive olur. **TNF reseptörleri** ise ölüm reseptörleri aracılığıyla yürütülen **ekstrensek yolakta** rol oynar. Bu nedenle D seçeneği yanlıştır.",
