    "question": "Gastrointestinal sistemde görülen yavaş dalgalarla ilgili hamgi ifade doğrudur?",
    "options": [
      {
        "letter": "A",
        "text": "Barsaktaki segmentasyonu oluşturur."
      },
      {
        "letter": "B",
        "text": "Sindirim sisteminde görülen aksiyon potansıyelidir."
      },
      {
        "letter": "C",
        "text": "Parasempatik uyarılma sonucunda hiperpolarızasyon görülür. =>"
      },
      {
        "letter": "D",
        "text": "Cajal'ın interstisyel hücreleri tarafından oluşturulur. ✓"
      },
      {
        "letter": "E",
        "text": "Oluşumunda temel olarak Ca iyonu rol oynar."
      }
    ],
    "answer": "D",
    "open_answer": "",
    "explanation": "Gastrointestinal düz kasın bazal elektriksel ritmini oluşturan yavaş dalgalar, düz kas katmanları arasında bulunan ve intrensek pacemaker işlevi gören **Cajal'ın interstisyel hücreleri (ICC)** tarafından üretilir (D doğru). Yavaş dalgalar tek başına bağırsakta segmentasyon hareketini oluşturmaz; mekanik kasılma ve segmentasyon ancak eşik değer aşıldığında ortaya çıkan **diken (aksiyon) potansiyelleri** ile gerçekleşir (A yanlış). Yavaş dalgalar sindirim sisteminde görülen gerçek aksiyon potansiyelleri değil, eşik altı ritmik **dinlenim membran potansiyeli salınımlarıdır** (B yanlış). Parasempatik uyarı (asetilkolin) hiperpolarizasyon değil **depolarizasyon** oluşturarak diken potansiyeli sıklığını artırır; hiperpolarizasyona sempatik uyarı yol açar (C yanlış). Düz kasta **Ca²⁺** girişi esas olarak yavaş dalgaların üzerinde oluşan **diken (aksiyon) potansiyelleri** ve kasılma aşamasında temel rol oynar; yavaş dalgaların kökeni Cajal hücrelerindeki pacemaker iyon akımlarıdır (E yanlış).",
    "note": "Cevap anahtarı tıbbi literatüre göre tamamlanmıştır.",
