    "explanation": "Karaciğerin çift kanlanması sayesinde portal triadlardan giren oksijenli **hepatik arter** kanı ile besinden zengin **portal ven** kanı, **karaciğer sinüzoidlerine dökülüp karışarak** hepatosit kordonları arasından santral vene doğru akar (B doğru). Hepatositlerden ve sinüzoidlerden geçen kan karaciğeri portal venle değil, santral venler ve hepatik venler (vv. hepaticae) aracılığıyla vena cava inferior'a dökülerek terk eder (A yanlış). Karaciğerde A vitamini depolanmasından sorumlu hücreler Disse aralığındaki Ito (stellate) hücreleridir; Kupffer hücreleri ise sinüzoid lümenindeki yerleşik makrofajlardır (C yanlış). Kan akımı santral vene doğru sentripetal iken safra kanalcıklarındaki safra akımı tam tersine merkezden portal alana doğru santrifügaldir (D yanlış). Karaciğer sinüzoid endotel hücrelerindeki fenestralar (pencereler) klasik pencereli kapillerlerden farklı olarak diyaframsızdır ve altında belirgin sürekli bazal lamina bulunmaz (E yanlış).",
