    "professor": "Bülent Mızrak",
    "question": "6 yaşındaki bir çocukta Stafilokokus aureus ve Strptokokus pnömonie gibi pyojenik bakteriler ile rekürran enfeksiyonlar hikayesi var. Enfeksiyonlar nötrofil lökositozu ile birliktedir. Yumuşak doku nekrozu gösteren bir alandan alınan biyopsi örneğinde mikroorganizamalar izleniyor, ancak çok az nötrofil lökosti mevcut. Nötrofil fonksiyonunu gösteren bir testte \"rolling\" (yuvarlanma)de defekt saptanıyor. Bu çocuğun enfeksiyona yatkınlığı, hangi moleküldeki bir defekt ile ilişkilidir?",
