    "subject": "Patoloji",
    "professor": "Bülent Mızrak",
    "question": "11 yaşında bir kız çocuğu hepatit A'ya yakalandı ve 1 haftadır hafif mide bulantısı yaşıyor. Fizik muayenede, minimal sağ üst kadran hassasiyeti ve skleral sarılığı var. Laboratuvar bulguları arasında serum aspartat transaminazı (AST) 68 U/L, alanin transaminazı (ALT) 75 U/L, ve toplam bilirubin 5,1 mg/dL. Laboratuvar bulguları en çok hepatositlerinde aşağıdaki değişikliklerden hangisinin sonucu olabilir?",
