    "q_num": 13,
    "subject": "Tıbbi Genetik",
    "professor": "Mehmet Gökcü",
    "question": "Aşağıdakilerden hangisi pedigriye göre bu ailede olabilecek genetik hastalıkla aynı kalıtım paternine sahip olması beklenmez?",
    "options": [
      {
        "letter": "A",
        "text": "Leber Herediter Optik Nöropati (LHON)"
      },
      {
        "letter": "B",
        "text": "Kearns Sayre Sendromu"
      },
      {
        "letter": "C",
        "text": "Hemofili A (Ağır Form)"
      },
      {
        "letter": "D",
        "text": "Mitokondriyal Ensefalopati Laktik Asidoz Stroke (MELAS)"
      },
      {
        "letter": "E",
        "text": "Myoclonic Epilepsy and Ragged Red Fibers (MERRF)"
      }
    ],
    "answer": "C",
    "open_answer": "",
    "explanation": "LHON, MELAS, MERRF ve Kearns-Sayre sendromları maternal aktarılan mitokondriyal DNA hastalıklarıdır. **Hemofili A** ise X kromozomuna bağlı resesif kalıtılan nükleer bir monogenik hastalıktır.",
    "note": "",
    "q_type": "mcq",
    "incomplete": false,
