    "question": "Fenilketonürili çocuklarda normal beyin gelişimini sağlamada en çok fenilalanin açısından düşük bir diyet etkilidir. Bu tedavi metabolik disfonksiyonun düzeltilmesine yönelik yaklaşımlardan hangisidir?",
