    "year": "2023-2024",
    "q_num": 29,
    "subject": "Farmakoloji",
    "professor": "Numan Taşpınar",
    "question": "Bir ilacın farklı fizyolojik etki mekanizmasıyla ortaya çıkan, yalın toksik etki için aşağıdakilerden hangisi örnek gösterilebilir?",
    "options": [
      {
        "letter": "A",
        "text": "Radyo aktif maddelerin genetik yapı içerisinde ortaya çıkardığı tek nükleotid polimorfizimleri."
      },
      {
        "letter": "B",
        "text": "Duyarlılığı olan kişilerde ilacın normal dozuna bağlı olarak oluşan etki."
      },
      {
        "letter": "C",
        "text": "Hücre gelişmesinin baskılanması."
      },
      {
        "letter": "D",
        "text": "Mide asit salınımını baskılamak için kullanılan telenzepinin ağız kuruluğu yapması. -Doğru Seçenek"
      },
      {
        "letter": "E",
        "text": "İlaın kimyasal yapısına bağlı olarak allerjik reaksiyon oluşması."
      }
    ],
    "answer": "D",
    "open_answer": "",
    "explanation": "M₁ selektif antimuskarinik **telenzepinin** mide asit salgısını azaltırken tükürük bezlerindeki muskarinik reseptörleri de inhibe edip **ağız kuruluğu yapması**, ilacın doğrudan bilinen farmakolojik mekanizması üzerinden gelişen öngörülebilir **yalın toksik etki** örneğidir (D doğru). Radyoaktif maddelerin genetik materyalde oluşturduğu tek nükleotid polimorfizmleri ve mutasyonlar yalın toksik etki değil, genotoksik/mutajenik özel toksik etkidir (A yanlış). Duyarlılığı olan kişilerde normal dozda ortaya çıkan abartılı etki yalın toksik etki değil, hipereaktivite veya duyarlılık artışıdır (B yanlış). Hücre gelişmesinin baskılanması farklı bir hedef organda fizyolojik yan etki örneği değil, genel sitotoksisite veya teratojenik toksisitedir (C yanlış). İlacın kimyasal yapısına karşı gelişen alerjik reaksiyon dozdan bağımsız immün aracılı aşırı duyarlılık yanıtıdır, yalın toksik etki değildir (E yanlış).",
    "note": "Cevap anahtarı tıbbi literatüre göre tamamlanmıştır.",
