    "explanation": "Su ve yağ fazlarının emülsiyonu şeklinde formüle edilen **krem**, deriye ve mukozaya uygulanan klasik bir yarı-katı farmasötik şekildir (tablet ve kapsül katı, solüsyon ve süspansiyon ise sıvıdır).",
    "note": "",
